 # waiting-only remainder does not dead-end
 fresh(page,'UIF-03','SCR-014'); page.click('[data-val03-receipt="VAL03-R4"]'); page.click('[data-val03-slice="VAL03-S7"]'); page.click('[data-val03-action="open-review"]'); page.click('[data-val03-action="confirm-value"]'); ck('BJ03 waiting-only remainder does not offer continue',page.locator('[data-val03-action="continue-remaining"]').count()==0 and 'đang chờ căn cứ' in txt(page).lower())
