 page.evaluate('activeScreenId="SCR-019";stateByScreen["SCR-019"]="UNKNOWN";render();'); ck('BJ03 UNKNOWN has no confirm retry',page.locator('[data-val03-action="confirm-value"]').count()==0 and 'Không gửi lại' in txt(page))
