 # BJ13 multi-target/method/closed period
 fresh(page,'UIF-13','SCR-085'); page.click('[data-val13-task="LC13-001"]'); ck('BJ13 exact scope spans multiple receipts','PN-260816-04' in txt(page) and 'PN-260821-03' in txt(page)); page.click('[data-val13-action="scope-to-allocation"]'); ck('BJ13 multiple allowed methods start unselected',page.locator('[data-val13-method]').input_value()==''); page.locator('[data-val13-method]').select_option('FIXTURE_VALUE'); alloc_sum=page.evaluate('val13Preview().reduce((s,x)=>s+x.allocatedAmount,0)'); amount=page.evaluate('val13Current().normalizedAmount'); ck('BJ13 allocation reconciles exactly',alloc_sum==amount); ck('BJ13 closed period shows original and posting periods','Kỳ gốc' in txt(page) and 'Kỳ ghi nhận' in txt(page) and '08/2026' in txt(page) and '09/2026' in txt(page)); page.click('[data-val13-action="open-review"]'); page.evaluate('val13ApplySourceUpdate()'); ck('BJ13 stale source blocks final commit','Tạo lại phân bổ' in txt(page) and page.locator('[data-val13-action="confirm-late-cost"]').count()==0)
 # FX and negative source
 fresh(page,'UIF-13','SCR-085'); page.click('[data-val13-task="LC13-002"]'); page.click('[data-val13-action="scope-to-allocation"]'); ck('BJ13 foreign currency exposes accounting FX','Tỷ giá Kế toán' in txt(page)); fresh(page,'UIF-13','SCR-085'); page.click('[data-val13-task="LC13-004"]'); page.click('[data-val13-action="scope-to-allocation"]'); ck('BJ13 negative purchase adjustment preserved','−' in txt(page) or '-350.000' in txt(page))
 # BJ13 large target set
 fresh(page,'UIF-13','SCR-086'); page.evaluate('''val13SelectedTaskId="LC13-001";let t=val13Current(),b=t.targets[0];for(let i=0;i<22;i++){t.targets.push({...b,id:"SCALE13-"+i,lineId:"LINE"+i,receipt:"PN-SCALE-"+i,product:"Sản phẩm dài "+i,lot:"LOT"+i,qty:i+1,receivedValue:100000+i*1000,selected:true});}render();'''); geom=page.locator('.app-content').evaluate('(e)=>({sw:e.scrollWidth,cw:e.clientWidth,sh:e.scrollHeight,ch:e.clientHeight})'); ck('BJ13 20+ targets vertically scalable',geom['sh']>geom['ch'] and geom['sw']<=geom['cw']+1)
